class Stage1ChannelCoverageTest {
    @BeforeAll static void start()throws Exception{initialize();}
    @AfterAll static void end()throws Exception{finish();}
    @BeforeEach void refresh(){new Stage1PersistenceTest().freshManagerSessions();}
    static String readyRelation(OwnerFixture owner,String config)throws Exception{String id=channelRelationFixture(owner,config);var row=relationCommand(id,1,"submit");for(int i=0;i<3;i++)row=relationCommand(id,row.get("version").getAsLong(),"query");relationCommand(id,row.get("version").getAsLong(),"enable");return id;}
    @Test void ordinaryWechatSummaryIsSeparateMaskedReadOnlyAndNeverAFallback()throws Exception{
        var original=db.rows("SELECT * FROM li_setting WHERE id='WECHAT_PAYMENT'");String privateKey="S1_TEST_PRIVATE_KEY_"+req(),apiKey="S1_TEST_API_KEY_"+req(),merchant="S1_TEST_MERCHANT_"+req(),app="S1_TEST_APP_"+req();
        try{
            if(original.isEmpty())db.update("INSERT INTO li_setting(id,create_by,delete_flag,setting_value) VALUES('WECHAT_PAYMENT','S1_TEST',0,'{}')");
            db.update("UPDATE li_setting SET setting_value=?,delete_flag=0 WHERE id='WECHAT_PAYMENT'",write(map("mchId",merchant,"mpAppId",app,"apiKey3",apiKey,"apiclientKey",privateKey,"publicKey",privateKey)));
            var before=db.required("SELECT * FROM li_setting WHERE id='WECHAT_PAYMENT'");var summary=call(get(Stage1Routes.MANAGER+"/channel-configs"),channel,null,200).getAsJsonObject("ordinaryWechat");assertEquals("CONFIGURED",summary.get("state").getAsString());assertEquals("ORDINARY_WECHAT",summary.get("type").getAsString());assertFalse(summary.get("p0Fallback").getAsBoolean());assertFalse(summary.get("externalVerified").getAsBoolean());assertTrue(summary.get("apiKey3Configured").getAsBoolean());assertTrue(summary.get("apiclientKeyConfigured").getAsBoolean());for(String sentinel:List.of(privateKey,apiKey,merchant,app))assertFalse(summary.toString().contains(sentinel));assertEquals(before,db.required("SELECT * FROM li_setting WHERE id='WECHAT_PAYMENT'"));
            call(get(Stage1Routes.MANAGER+"/channel-configs"),reviewer,null,403);
            db.update("UPDATE li_setting SET setting_value='invalid synthetic document' WHERE id='WECHAT_PAYMENT'");summary=call(get(Stage1Routes.MANAGER+"/channel-configs"),channel,null,200).getAsJsonObject("ordinaryWechat");assertEquals("UNREADABLE",summary.get("state").getAsString());assertFalse(summary.has("apiKey3Configured"));
            db.update("UPDATE li_setting SET delete_flag=1 WHERE id='WECHAT_PAYMENT'");assertEquals("NOT_CONFIGURED",call(get(Stage1Routes.MANAGER+"/channel-configs"),channel,null,200).getAsJsonObject("ordinaryWechat").get("state").getAsString());
        }finally{if(original.isEmpty())db.update("DELETE FROM li_setting WHERE id='WECHAT_PAYMENT' AND create_by='S1_TEST'");else db.update("UPDATE li_setting SET setting_value=?,delete_flag=? WHERE id='WECHAT_PAYMENT'",original.get(0).get("setting_value"),original.get(0).get("delete_flag"));}
    }
    @Test void configurationIsSeparateIdempotentVersionedAndCannotDowngradeRequestMode()throws Exception{
        var ordinary=db.rows("SELECT * FROM li_setting ORDER BY id");String digest=hash(ordinary);
        var owner=ownerFixture();String agreement=agreementFixture(owner,0,LocalDate.now(Stage1Rules.ZONE),null);ruleFixture(owner,agreement,0);String config=channelConfigFixture(500),relation=readyRelation(owner,config);
        var body=map("requestId",req(),"expectedVersion",2,"reason","S1_TEST配置禁用不删历史");var first=call(post(Stage1Routes.MANAGER+"/channel-configs/"+config+"/disable"),channel,body,200);assertEquals(first,call(post(Stage1Routes.MANAGER+"/channel-configs/"+config+"/disable"),channel,body,200));body.put("reason","S1_TEST不同请求内容");call(post(Stage1Routes.MANAGER+"/channel-configs/"+config+"/disable"),channel,body,409);
        assertFalse((Boolean)eligibility.evaluate(owner.store(),category,null).get("MOCK_READY"));call(post(Stage1Routes.MANAGER+"/channel-configs/"+config+"/enable"),channel,map("requestId",req(),"expectedVersion",3,"reason","S1_TEST配置恢复仍须核证"),200);assertFalse((Boolean)eligibility.evaluate(owner.store(),category,null).get("MOCK_READY"));assertEquals(1,db.count("SELECT COUNT(*) FROM li_p0_submerchant_relation WHERE id=?",relation));assertTrue(db.count("SELECT COUNT(*) FROM li_p0_channel_config_history WHERE config_id=?",config)>=5);
        var configRow=db.required("SELECT * FROM li_p0_channel_config WHERE id=?",config);var a=map("requestId",req(),"expectedVersion",4,"name","S1_TEST竞争甲","providerMchid",configRow.get("provider_mchid"),"paymentAppId",configRow.get("payment_appid"),"reason","S1_TEST配置版本竞争");var b=new LinkedHashMap<>(a);b.put("requestId",req());b.put("name","S1_TEST竞争乙");Stage1ConcurrencyTest.race(new Stage1ConcurrencyTest.Command("PUT",Stage1Routes.MANAGER+"/channel-configs/"+config+"/draft",channel,a),new Stage1ConcurrencyTest.Command("PUT",Stage1Routes.MANAGER+"/channel-configs/"+config+"/draft",manager("710000000000000003"),b));assertEquals(5,db.count("SELECT config_version FROM li_p0_channel_config WHERE id=?",config));
        call(put(Stage1Routes.MANAGER+"/channel-configs/"+config+"/draft"),reviewer,a,403);for(String field:List.of("mode","environment","provider")){var input=new LinkedHashMap<>(a);input.put("requestId",req());input.put(field,field.equals("provider")?"WECHAT":"MOCK");call(put(Stage1Routes.MANAGER+"/channel-configs/"+config+"/draft"),channel,input,422);}
        String mode=settings.getMode();try{settings.setMode("REAL");var result=call(get(Stage1Routes.STORE+"/eligibility").param("mode","MOCK").param("environment","DEV").header("X-Channel-Mode","MOCK"),owner.login().session(),null,200);assertEquals("REAL",result.get("authorizedMode").getAsString());assertFalse(result.get("REAL_READY").getAsBoolean());}finally{settings.setMode(mode);}assertEquals(digest,hash(db.rows("SELECT * FROM li_setting ORDER BY id")));
    }
    @Test void receiverCreationDeduplicatesAcrossStoresAndRejectsUntrustedOrFutureEvidence()throws Exception{
        var a=ownerFixture();var b=ownerFixture();String config=channelConfigFixture(500),ra=channelRelationFixture(a,config),rb=channelRelationFixture(b,config),account="MOCK_"+db.id();var body=map("requestId",req(),"configId",config,"displayName","S1_TEST平台接收","mockAccount",account,"reason","S1_TEST去重");var other=new LinkedHashMap<>(body);other.put("requestId",req());Stage1ConcurrencyTest.race(new Stage1ConcurrencyTest.Command("POST",Stage1Routes.MANAGER+"/receivers",channel,body),new Stage1ConcurrencyTest.Command("POST",Stage1Routes.MANAGER+"/receivers",manager("710000000000000003"),other));
        String id=id(db.required("SELECT id FROM li_p0_receiver_relation WHERE config_id=?",config),"id");assertEquals(1,db.count("SELECT COUNT(*) FROM li_p0_receiver_relation WHERE config_id=?",config));for(String relation:List.of(ra,rb))call(put(Stage1Routes.MANAGER+"/submerchants/"+relation+"/receiver"),channel,map("requestId",req(),"expectedVersion",1,"receiverId",id,"reason","S1_TEST两店引用同关系"),200);
        call(post(Stage1Routes.MANAGER+"/receivers/"+id+"/enable"),channel,map("requestId",req(),"expectedVersion",0,"reason","S1_TEST手填不可信"),409);var current=call(post(Stage1Routes.MANAGER+"/receivers/"+id+"/sync"),channel,map("requestId",req(),"expectedVersion",0,"reason","S1_TEST本机契约"),200).getAsJsonObject("receiver");long version=current.get("version").getAsLong();var original=db.required("SELECT * FROM li_p0_receiver_relation WHERE id=?",id);
        for(String source:List.of("UNVERIFIED","API_REGISTERED_VERIFIED","DEFAULT_PLATFORM_VERIFIED")){db.update("UPDATE li_p0_receiver_relation SET trust_source=? WHERE id=?",source,id);call(post(Stage1Routes.MANAGER+"/receivers/"+id+"/enable"),channel,map("requestId",req(),"expectedVersion",version,"reason","S1_TEST模式来源不互代"),409);}db.update("UPDATE li_p0_receiver_relation SET trust_source=? WHERE id=?",original.get("trust_source"),id);
        for(Instant at:List.of(clock.instant().plusSeconds(60),clock.instant().minusSeconds(86400))){db.update("UPDATE li_p0_receiver_relation SET verified_at=? WHERE id=?",at,id);call(post(Stage1Routes.MANAGER+"/receivers/"+id+"/enable"),channel,map("requestId",req(),"expectedVersion",version,"reason","S1_TEST证据时间"),409);}db.update("UPDATE li_p0_receiver_relation SET verified_at=? WHERE id=?",original.get("verified_at"),id);call(post(Stage1Routes.MANAGER+"/receivers/"+id+"/enable"),channel,map("requestId",req(),"expectedVersion",version,"reason","S1_TEST合法恢复"),200);
        var invalid=new LinkedHashMap<>(body);invalid.put("requestId",req());invalid.put("receiverType","PERSONAL_OPENID");call(post(Stage1Routes.MANAGER+"/receivers"),channel,invalid,422);call(put(Stage1Routes.MANAGER+"/submerchants/"+ra+"/receiver"),channel,map("requestId",req(),"expectedVersion",2,"receiverId",rb,"reason","S1_TEST子商户不是接收方"),404);
        String env=settings.getEnvironment();try{settings.setEnvironment("DEV");var cfg=call(post(Stage1Routes.MANAGER+"/channel-configs"),channel,Stage1ChannelBoundaryTest.configuration("MOCK","S1_TEST异环境","S1_TEST隔离"),200);var separate=new LinkedHashMap<>(body);separate.put("requestId",req());separate.put("configId",cfg.get("id").getAsString());var receiver=call(post(Stage1Routes.MANAGER+"/receivers"),channel,separate,200);assertNotEquals(id,receiver.get("id").getAsString());settings.setEnvironment(env);call(put(Stage1Routes.MANAGER+"/submerchants/"+ra+"/receiver"),channel,map("requestId",req(),"expectedVersion",2,"receiverId",receiver.get("id").getAsString(),"reason","S1_TEST跨环境引用"),404);}finally{settings.setEnvironment(env);}
        assertEquals(2,db.count("SELECT COUNT(*) FROM li_p0_submerchant_relation WHERE receiver_id=?",id));
    }
    @Test void receiverCannotReplaceSubmerchantAndAmbiguousOrForeignAccountsNeverBecomeReady()throws Exception{
        var owner=ownerFixture();String agreement=agreementFixture(owner,500,LocalDate.now(Stage1Rules.ZONE),null);ruleFixture(owner,agreement,500);String config=channelConfigFixture(1000);var receiver=call(post(Stage1Routes.MANAGER+"/receivers"),channel,map("requestId",req(),"configId",config,"displayName","S1_TEST独立接收方","mockAccount","MOCK_"+db.id(),"reason","S1_TEST接收不代二级商户"),200);String receiverId=receiver.get("id").getAsString();assertFalse((Boolean)eligibility.evaluate(owner.store(),category,null).get("MOCK_READY"));call(post(Stage1Routes.MANAGER+"/submerchants"),channel,map("requestId",req(),"storeId",owner.store(),"configId",config,"existingSubMchid",receiverId,"reason","S1_TEST拒绝混用"),422);
        String first=readyRelation(owner,config);var original=db.required("SELECT * FROM li_p0_submerchant_relation WHERE id=?",first);var other=ownerFixture();String second=channelRelationFixture(other,config);var initial=relationCommand(second,1,"submit");String actor=sessions.verifyAccess(channel.accessToken(),SessionDomain.MANAGER,apps.application(SessionDomain.MANAGER)).identity().subject();var op=Stage1ChannelRecoveryTest.interrupted(second,actor);var application=db.required("SELECT * FROM li_p0_channel_application WHERE id=?",initial.get("applicationId").getAsString());org.springframework.test.util.ReflectionTestUtils.invokeMethod(channels,"finish",op,object(map("applyment_id",id(application,"applyment_id"),"out_request_no",application.get("out_request_no"),"applyment_state","FINISH","sub_mchid",original.get("sub_mchid"))),map("verificationState","VERIFIED","sourceMode","MOCK"),null,null);
        assertEquals("CHANNEL_ACCOUNT_CONFLICT",db.required("SELECT failure_code FROM li_p0_channel_operation WHERE id=?",op.get("id")).get("failure_code"));assertEquals(original,db.required("SELECT * FROM li_p0_submerchant_relation WHERE id=?",first));assertEquals(1,db.count("SELECT COUNT(*) FROM li_p0_submerchant_relation WHERE active_account_key=?",original.get("active_account_key")));call(post(Stage1Routes.MANAGER+"/submerchants/"+second+"/enable"),channel,map("requestId",req(),"expectedVersion",db.count("SELECT version FROM li_p0_submerchant_relation WHERE id=?",second),"reason","S1_TEST冲突不能启用"),409);
        assertThrows(org.springframework.dao.DuplicateKeyException.class,()->db.update("UPDATE li_p0_submerchant_relation SET active_store_key=? WHERE id=?",original.get("active_store_key"),second));
        // Simulate an imported corrupt pointer without dropping any unique constraint.
        try{db.update("UPDATE li_p0_submerchant_relation SET store_id=? WHERE id=?",owner.store(),second);var result=object(eligibility.evaluate(owner.store(),category,null));assertFalse(result.get("MOCK_READY").getAsBoolean());assertTrue(result.get("reasons").toString().contains("CHANNEL_PENDING"));assertEquals(2,db.count("SELECT COUNT(*) FROM li_p0_submerchant_relation WHERE store_id=? AND active_store_key IS NOT NULL",owner.store()));}finally{db.update("UPDATE li_p0_submerchant_relation SET store_id=? WHERE id=?",other.store(),second);}
    }
    @Test void relationshipReplacementPreservesHistoryAndNeverTreatsOldAccountAsCurrentEvidence()throws Exception{
        var owner=ownerFixture();String agreement=agreementFixture(owner,0,LocalDate.now(Stage1Rules.ZONE),null);ruleFixture(owner,agreement,0);String config=channelConfigFixture(1000),old=readyRelation(owner,config);assertTrue((Boolean)eligibility.evaluate(owner.store(),category,null).get("MOCK_READY"));var input=map("requestId",req(),"storeId",owner.store(),"configId",config,"reason","S1_TEST不自动择一");call(post(Stage1Routes.MANAGER+"/submerchants"),channel,input,409);
        String account=id(db.required("SELECT sub_mchid FROM li_p0_submerchant_relation WHERE id=?",old),"sub_mchid");input.put("requestId",req());input.put("predecessorId",old);input.put("existingSubMchid",account);var replacement=call(post(Stage1Routes.MANAGER+"/submerchants"),channel,input,200);assertNotEquals(old,replacement.get("id").getAsString());assertEquals("DRAFT",replacement.get("applicationState").getAsString());assertEquals("UNVERIFIED",replacement.get("capabilityState").getAsString());assertFalse((Boolean)eligibility.evaluate(owner.store(),category,null).get("MOCK_READY"));assertFalse((Boolean)eligibility.evaluate(owner.store(),category,null).get("REAL_READY"));var previous=db.required("SELECT * FROM li_p0_submerchant_relation WHERE id=?",old);assertFalse(flag(previous,"enabled"));assertNull(previous.get("active_store_key"));assertEquals(account,previous.get("sub_mchid"));assertTrue(db.count("SELECT COUNT(*) FROM li_p0_channel_operation WHERE object_id=?",old)>0);call(post(Stage1Routes.MANAGER+"/submerchants/"+old+"/enable"),channel,map("requestId",req(),"expectedVersion",previous.get("version"),"reason","S1_TEST旧关系不能恢复"),409);
    }
}
